result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "nested_cv.py", "content": """"Nested cross-validation done right.

Compares the honest estimate (outer loop of nested CV) against the
optimistically biased single-loop estimate (GridSearchCV.best_score_).
"""
import time

import numpy as np
from sklearn.datasets import make_classification
from sklearn.model_selection import GridSearchCV, cross_val_score
from sklearn.svm import SVC


def get_data():
    return make_classification(
        n_samples=600, n_features=12, n_informative=6, random_state=3
    )


def make_grid():
    param_grid = {"C": [0.1, 1, 10], "gamma": [0.01, 0.1, 1]}
    return GridSearchCV(
        estimator=SVC(), param_grid=param_grid, cv=5, n_jobs=-1
    )


def nested_cv_score():
    """Honest generalization estimate: outer 5-fold CV over full inner tuning."""
    X, y = get_data()
    outer = cross_val_score(make_grid(), X, y, cv=5)
    return float(np.mean(outer)), float(np.std(outer))


def biased_single_loop_score():
    """Optimistic estimate: tune and report on the same data."""
    X, y = get_data()
    grid = make_grid()
    grid.fit(X, y)
    return float(grid.best_score_)


def main():
    t0 = time.time()
    nested_mean, nested_std = nested_cv_score()
    best_score = biased_single_loop_score()
    elapsed = time.time() - t0

    print(
        f"Nested CV outer accuracy: {nested_mean:.4f} +/- {nested_std:.4f}"
    )
    print(
        f"Single-loop best_score_:  {best_score:.4f} "
        f"(bias: {best_score - nested_mean:+.4f}) [{elapsed:.1f}s]"
    )
    return nested_mean, best_score


if __name__ == "__main__":
    main()
